<template>
  <div v-if="views.length" class="shared-view-previews">
    <span class="shared-view-previews-label">Sample Shared Views</span>
    <ul class="shared-view-previews-list">
      <li v-for="view in views" :key="view.id">
        <router-link :to="`/view/${view.id}`">
          <span class="shared-view-previews-copy">
            <span class="shared-view-previews-question">&ldquo;{{ view.question }}&rdquo;</span>
            <span class="shared-view-previews-meta">{{ sourceLabel(view.source_count) }} · {{ dateLabel(view.created_at) }}</span>
          </span>
          <ArrowUpRightIcon class="shared-view-previews-arrow" />
        </router-link>
      </li>
    </ul>
    <router-link class="shared-view-previews-explore" to="/views">
      <span>Explore more</span>
      <span class="shared-view-previews-explore-arrow" aria-hidden="true">&rarr;</span>
    </router-link>
  </div>
</template>

<script>
import { listPublicViews } from '../../utils/viewShareSite';
import ArrowUpRightIcon from '../ui/ArrowUpRightIcon.vue';

export default {
  name: 'SharedViewPreviews',
  components: { ArrowUpRightIcon },
  data() {
    return {
      views: [],
    };
  },
  mounted() {
    this.loadViews();
  },
  methods: {
    async loadViews() {
      try {
        const data = await listPublicViews();
        this.views = (data.views || [])
          .slice()
          .sort((a, b) => Number(b.featured || 0) - Number(a.featured || 0))
          .slice(0, 3);
      } catch {
        this.views = [];
      }
    },
    sourceLabel(count) {
      return `${count} original ${count === 1 ? 'piece' : 'pieces'}`;
    },
    dateLabel(timestamp) {
      if (!timestamp) return 'Date unavailable';
      return new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })
        .format(new Date(timestamp));
    },
  },
};
</script>

