<template>
  <div class="translation-control" :class="{ 'is-visible': visible }">
    <button
      type="button"
      class="translation-action"
      :disabled="loading"
      :aria-expanded="visible ? 'true' : 'false'"
      @click="$emit('toggle')"
      @pointerup="releaseFocus"
    >
      <svg class="translation-icon" viewBox="0 0 20 20" aria-hidden="true">
        <path d="M3.25 4.25h8.5M7.5 2.5v1.75m-2.7 3.1c1.05 2.15 2.75 3.7 5.15 4.7M10.6 7.35c-.85 2.25-2.55 4.25-5.4 5.6M12.2 16.8l2.45-6.3 2.45 6.3m-3.95-1.45h3" />
      </svg>
      <span>{{ label }}</span>
      <span v-if="loading" class="translation-spinner" aria-hidden="true" />
    </button>
    <a
      v-if="visible"
      class="translation-attribution"
      href="https://translate.google.com/"
      target="_blank"
      rel="noopener noreferrer"
      aria-label="Powered by Google Translate"
    >
      <img class="translation-attribution-light" src="/assets/google-translate/color-regular@2x.png" alt="Powered by Google Translate">
      <img class="translation-attribution-dark" src="/assets/google-translate/white-regular@2x.png" alt="">
    </a>
    <p class="translation-status" aria-live="polite">{{ status }}</p>
  </div>
</template>

<script>
export default {
  name: 'ViewTranslationControl',
  props: {
    loading: { type: Boolean, default: false },
    visible: { type: Boolean, default: false },
    loaded: { type: Boolean, default: false },
    error: { type: String, default: '' },
  },
  emits: ['toggle'],
  computed: {
    label() {
      if (this.loading) return 'Translating…';
      if (this.visible) return 'Hide English';
      if (this.loaded) return 'Show English';
      return this.error ? 'Try translation again' : 'Translate with Google';
    },
    status() {
      if (this.loading) return 'Preparing the English translation.';
      return this.error;
    },
  },
  methods: {
    releaseFocus(event) {
      if (event.pointerType !== 'keyboard') event.currentTarget.blur();
    },
  },
};
</script>

